create table if not exists public.flip_games (id uuid primary key default gen_random_uuid(),access_code text not null unique check(access_code~'^[0-9]{6}$'),words jsonb not null,active boolean not null default true,ends_at timestamptz not null,created_at timestamptz not null default now());
create table if not exists public.flip_players (id uuid primary key default gen_random_uuid(),game_id uuid references public.flip_games(id) on delete cascade,nickname text not null,team text not null check(team in('red','blue')),participant_key text not null,unique(game_id,participant_key));
create table if not exists public.flip_tiles (id uuid primary key default gen_random_uuid(),game_id uuid references public.flip_games(id) on delete cascade,word text not null,owner text check(owner in('red','blue')),unique(game_id,word));
alter table public.flip_games enable row level security;alter table public.flip_players enable row level security;alter table public.flip_tiles enable row level security;
